import SwiftUI
struct FieldRowView: View { @Binding var field: ResumeField; var onDelete: ()->Void; var body: some View { HStack(alignment:.firstTextBaseline,spacing:12){ TextField("Label",text:$field.label).font(DS.FontToken.label).foregroundStyle(DS.ColorToken.textMuted).frame(width:95); TextField("Value",text:$field.value,axis:.vertical).font(field.isBold ? .system(size:16,weight:.semibold) : DS.FontToken.body).foregroundStyle(DS.ColorToken.text) }.padding(.vertical,6).swipeActions(edge:.trailing){Button(role:.destructive,action:onDelete){Label("Delete",systemImage:"trash")}} } }
